<template>
<view class="page">
  <view class="nav"><view class="back-button" @click="back">‹ {{ tr('Back') }}</view><text>{{ tr('Daily Goals') }}</text><text class="date">{{ day.slice(5) }}</text></view>
  <view class="hero"><text class="eyebrow">{{ tr('TODAY’S PLAN') }}</text><view class="hero-row"><view><text class="hero-title">{{ tr('Small steps, every day') }}</text><text class="hero-sub">{{ completed }} / 4 {{ tr('goals completed') }}</text></view><view class="hero-score">{{ overall }}<text>%</text></view></view><view class="hero-track"><view :style="{width:overall+'%'}" /></view></view>
  <view class="heading"><text>{{ tr('Your daily targets') }}</text><text class="muted">{{ tr('Tap to adjust') }}</text></view>
  <view class="goal" v-for="item in items" :key="item.key">
    <view class="goal-head"><view class="icon" :style="{background:item.color+'18',color:item.color}">{{ item.icon }}</view><view class="goal-name"><text>{{ tr(item.title) }}</text><text class="muted">{{ tr(item.key==='measurements'?'Automatically counted':'Manual record') }}</text></view><text class="percent" :style="{color:item.color}">{{ item.progress }}%</text></view>
    <view class="numbers"><text class="current">{{ state.values[item.key] }}</text><text class="muted"> / {{ state.targets[item.key] }} {{ tr(item.unit) }}</text></view>
    <view class="track"><view :style="{width:item.progress+'%',background:item.color}" /></view>
    <view class="target-row"><text>{{ tr('Daily target') }}</text><view class="stepper"><text @click="adjust(item,-1)">−</text><text class="target">{{ state.targets[item.key] }} {{ tr(item.unit) }}</text><text @click="adjust(item,1)">+</text></view></view>
    <view class="record" v-if="item.key!=='measurements'"><view class="record-buttons"><text @click="add(item,-1)">− {{ item.step }} {{ tr(item.unit) }}</text><text :style="{color:item.color}" @click="add(item,1)">+ {{ item.step }} {{ tr(item.unit) }}</text></view><view class="exact"><text>{{ tr('Recorded today') }}</text><input type="digit" :value="state.values[item.key]" @blur="setValue(item,$event)" /><text>{{ tr(item.unit) }}</text></view></view>
  </view>
  <view class="note">{{ tr('Water, activity and sleep are recorded by you. These goals are saved on this phone for the current account.') }}</view>
  <button class="save" @click="save">{{ tr('Save daily targets') }}</button>
</view>
</template>
<script>
import {backToTab} from '@/utils/navigation.js';
import {getDataUrl} from '@/config/api.js';
import {goalDefinitions,readGoals,saveGoals,goalProgress,localDay} from '@/utils/goals.js';
export default {data:()=>({returnTo:'index',state:{targets:{},values:{}},userId:null,day:localDay()}),computed:{items(){return goalDefinitions.map(d=>({...d,progress:goalProgress(this.state.values[d.key]||0,this.state.targets[d.key]||d.target)}));},overall(){return Math.round(this.items.reduce((n,d)=>n+d.progress,0)/4);},completed(){return this.items.filter(d=>d.progress===100).length;}},onLoad(options){this.returnTo=options.returnTo==='profile'?'profile':'index';},onShow(){this.userId=uni.getStorageSync('user')?.id;this.day=localDay();this.state=readGoals(this.userId);const deviceId=uni.getStorageSync('selectedDeviceId');if(deviceId)uni.request({url:getDataUrl('rangeRecords'),data:{deviceId,startDate:this.day,endDate:this.day},success:r=>{if(r.data.errcode===0&&Array.isArray(r.data.data)){this.state.values.measurements=new Set(r.data.data.map(row=>row.id??row.measure_time)).size;this.persist();}}});},methods:{back(){backToTab(this.returnTo);},persist(){saveGoals(this.userId,this.state);},adjust(item,direction){this.state.targets[item.key]=Math.max(item.step,Math.min(item.max,Number((this.state.targets[item.key]+direction*item.step).toFixed(1))));this.persist();},add(item,direction){this.state.values[item.key]=Math.max(0,Number((this.state.values[item.key]+direction*item.step).toFixed(1)));this.persist();},setValue(item,event){const value=Number(event.detail.value);if(Number.isFinite(value)){this.state.values[item.key]=Math.max(0,Math.min(item.max*3,value));this.persist();}},save(){this.persist();uni.showToast({title:this.tr('Saved'),icon:'success'});}}};
</script>
<style scoped>
.back-button{padding:18rpx 18rpx 18rpx 0;min-width:110rpx;}
.page{padding:32rpx 28rpx 70rpx;background:#f5f6fb;min-height:100vh;color:#20283e;box-sizing:border-box}.nav{display:flex;justify-content:space-between;align-items:center;padding:28rpx 0 36rpx;font-size:28rpx}.nav>text:nth-child(2){font-size:34rpx;font-weight:700}.date,.muted{color:#8790a4;font-size:23rpx}.hero{background:linear-gradient(125deg,#7162da,#8a73e8);border-radius:32rpx;padding:36rpx;color:white;box-shadow:0 16rpx 35rpx #7766dd24}.eyebrow{font-size:21rpx;opacity:.8;letter-spacing:2rpx}.hero-row{display:flex;justify-content:space-between;align-items:center;margin:24rpx 0}.hero-title{display:block;font-size:36rpx;font-weight:700}.hero-sub{display:block;margin-top:12rpx;font-size:25rpx;opacity:.85}.hero-score{font-size:64rpx;font-weight:700}.hero-score text{font-size:24rpx}.hero-track,.track{height:12rpx;border-radius:20rpx;background:#ffffff30;overflow:hidden}.hero-track>view{height:100%;background:white;border-radius:20rpx}.heading{display:flex;justify-content:space-between;margin:40rpx 4rpx 24rpx;font-size:32rpx;font-weight:600}.goal{background:white;border-radius:28rpx;padding:30rpx;margin-bottom:24rpx;box-shadow:0 4rpx 18rpx #29375c04}.goal-head{display:flex;align-items:center;gap:20rpx}.icon{width:76rpx;height:76rpx;border-radius:24rpx;display:flex;align-items:center;justify-content:center;font-size:42rpx}.goal-name{flex:1}.goal-name>text{display:block;font-weight:600;font-size:30rpx}.goal-name>.muted{font-weight:400;font-size:22rpx;margin-top:6rpx}.percent{font-size:28rpx;font-weight:600}.numbers{margin:26rpx 0 18rpx}.current{font-size:48rpx;font-weight:700}.track{background:#f0f2f7;height:10rpx}.track>view{height:100%;border-radius:20rpx}.target-row{display:flex;align-items:center;justify-content:space-between;margin-top:26rpx;font-size:24rpx;color:#6f7890}.stepper{display:flex;align-items:center;gap:12rpx}.stepper>text:first-child,.stepper>text:last-child{width:52rpx;height:52rpx;line-height:52rpx;text-align:center;border-radius:14rpx;background:#f3f4fa;font-size:32rpx}.target{min-width:140rpx;text-align:center;color:#30384e;font-size:24rpx}.record{border-top:1px solid #f0f2f7;margin-top:22rpx;padding-top:20rpx}.record-buttons{display:flex;gap:18rpx}.record-buttons>text{flex:1;text-align:center;background:#f7f8fb;border-radius:16rpx;padding:16rpx;font-size:25rpx}.exact{display:flex;align-items:center;gap:12rpx;margin-top:20rpx;color:#8790a4;font-size:23rpx}.exact input{flex:1;min-width:0;background:#f7f8fb;text-align:right;border-radius:12rpx;padding:12rpx;color:#30384e}.note{font-size:23rpx;line-height:1.7;color:#8a92a4;margin:24rpx 8rpx}.save{background:#7763e2;color:white;font-size:28rpx;border-radius:22rpx;padding:22rpx}.save:after{border:0}
</style>